with tracer.start_as_current_span("fetch_prices") as span:
    for attempt in range(3):
        try:
            return client.get("/prices")
        except TimeoutError as e:
            span.add_event("retry", {"attempt": attempt + 1, "reason": "timeout"})
    span.set_attribute("retry.exhausted", True)

processors:
  tail_sampling:
    decision_wait: 10s
    policies:
      - { name: errors,  type: status_code, status_code: { status_codes: [ERROR] } }
      - { name: slow,    type: latency,     latency: { threshold_ms: 1000 } }
      - { name: sample,  type: probabilistic, probabilistic: { sampling_percentage: 5 } }
